--
-- Table structure for table `cliente_produto_duracao`
--

DROP TABLE IF EXISTS `cliente_produto_duracao`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cliente_produto_duracao` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `cliente_id` bigint unsigned NOT NULL,
  `produto_id` bigint unsigned NOT NULL,
  `duracao` int NOT NULL DEFAULT '30' COMMENT 'Duração média de uso em dias',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `cliente_produto_duracao_cliente_id_produto_id_unique` (`cliente_id`,`produto_id`),
  KEY `cliente_produto_duracao_produto_id_foreign` (`produto_id`),
  CONSTRAINT `cliente_produto_duracao_cliente_id_foreign` FOREIGN KEY (`cliente_id`) REFERENCES `clientes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `cliente_produto_duracao_produto_id_foreign` FOREIGN KEY (`produto_id`) REFERENCES `produtos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=194 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

