INSERT INTO `manual_itens` VALUES (1,'geral','cadastro','clientes','cadastrar_cliente','como cadastrar cliente','Cadastro de Clientes','Cadastrar um novo cliente para utilizar em vendas e pedidos.','Acesse Cadastro → Clientes. Clique em Novo Cliente. Preencha os dados do cliente como nome, telefone e endereço. Depois clique em Salvar.','Cadastrar telefone facilita localizar o cliente nas vendas.','Evite cadastrar o mesmo cliente duas vezes.',1,0,'2026-03-07 20:14:25'),(2,'geral','cadastro','clientes','editar_cliente','como editar cliente','Editar Cliente','Alterar ou atualizar os dados de um cliente já cadastrado.','Acesse Cadastro → Clientes. Localize o cliente desejado. Clique em Editar. Altere as informações necessárias e clique em Salvar.','Mantenha telefone e endereço sempre atualizados.',NULL,1,0,'2026-03-07 20:16:28'),(3,'geral','cadastro','clientes','excluir_cliente','como excluir cliente','Excluir Cliente','Remover um cliente do cadastro.','Acesse Cadastro → Clientes. Localize o cliente. Clique em Excluir e confirme a operação.',NULL,'Clientes que possuem vendas registradas podem não permitir exclusão.',1,0,'2026-03-07 20:17:16'),(4,'geral','cadastro','clientes','pesquisar_cliente','como pesquisar cliente','Pesquisar Cliente','Localizar clientes já cadastrados.','Acesse Cadastro → Clientes. Use o campo de pesquisa e digite o nome, telefone ou parte do nome do cliente.','Pesquisar pelo telefone costuma ser mais rápido.',NULL,1,0,'2026-03-07 20:17:38');
